#ifndef PARSER_INTERNAL_H
#define PARSER_INTERNAL_H

#include "array.h"  // ARRAY_TYPE
#include "ast.h"    // AstNode
#include "ctx.h"    // Ctx
#include "lexer.h"  // Token, TokenType

#include <stdbool.h>  // bool
#include <stddef.h>   // size_t

/**
 * @brief Function producing the next raw token from a token source.
 *
 * The real source is the lexer (see lexer_source_next); unit tests use a fixed
 * token array. The returned token is owned by the parser.
 */
typedef Token (*TokenSourceNext)(Ctx* ctx, void* source);

/**
 * @brief Stack of indentations of the currently open blocks
 */
ARRAY_TYPE(IndentStack, int);

/**
 * @brief Terminals of the precedence table (its rows and columns), in the
 * table's order
 */
typedef enum {
  PREC_MEMBER,   // .m, PERIOD IDENT
  PREC_PREFIX,   // pre, unary - and !
  PREC_MUL,      // mul, * /
  PREC_ADD,      // add, binary + -
  PREC_REL,      // rel, < > <= >=
  PREC_EQ,       // eq, == !=
  PREC_AND,      // and, &&
  PREC_OR,       // or, ||
  PREC_LPAREN,   // (
  PREC_RPAREN,   // )
  PREC_OPERAND,  // i, a whole operand (GLOSSARY.md, Operand)
  PREC_END,      // $, the bottom of a frame and the expression end
  PREC_TERMINAL_COUNT,
} PrecTerminal;

/**
 * @brief Kind of an entry of the precedence stack
 */
typedef enum {
  // A precedence terminal (terminal is valid)
  PREC_ENTRY_TERMINAL,
  // A reduced expression E (node is valid)
  PREC_ENTRY_EXPR,
  // The `<` marking where a handle starts
  PREC_ENTRY_HANDLE,
} PrecEntryKind;

/**
 * @brief Entry of the precedence stack
 */
typedef struct {
  PrecEntryKind kind;
  PrecTerminal terminal;
  // Subtree owned by the stack until it is attached (NULL when the entry has
  // none): the operand's node for i, the operator's node (children not yet
  // attached) for an operator, the expression for E
  AstNode* node;
} PrecEntry;

/**
 * @brief The precedence stack (GLOSSARY.md, Precedence stack), shared by all
 * expressions being parsed at once, each using its own frame above where it
 * started (guidance/parser-structure/adr/0004)
 */
ARRAY_TYPE(PrecStack, PrecEntry);

/**
 * @brief State of a running parse, owned by ctx->parser
 */
struct Parser {
  // Token source and its state
  TokenSourceNext next;
  void* source;

  // Current token, the LL table is indexed by it. Owned by the parser.
  Token current;

  // Peeked token (valid when has_peeked), see parser_peek. Owned by the parser.
  Token peeked;
  bool has_peeked;

  // Indentations of the open blocks, the bottom is always 0 (top level)
  IndentStack indents;

  // Block closes still to be delivered as INDENT tokens, and their position
  size_t pending_closes;
  Token pending_close;

  // Precedence stack; parser_cleanup destroys the subtrees left on it
  PrecStack prec_stack;
};

// === ENTRY POINT ===

/**
 * @brief Parses the whole program read from a token source into ctx->ast.
 *
 * Creates the parser state and the PROGRAM root (stored in ctx->ast before
 * parsing starts), parses from the start nonterminal of the LL table to the end
 * of input and frees the parser state. parser_parse is this function with the
 * lexer as the token source; unit tests pass a fixed token array.
 *
 * Syntax errors are reported with THROW(E_SYNTAX_ERROR, ...). After a THROW,
 * ctx_free releases the parser state and the partly built AST.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context, ctx->ast and
 * ctx->parser must be NULL
 * @param[in] next Token source function
 * @param[in] source State passed to next
 */
void parser_run(Ctx* ctx, TokenSourceNext next, void* source);

// === TOKEN LAYER ===

/**
 * @brief Creates the parser state in ctx->parser and reads the first token.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context, ctx->parser
 * must be NULL
 * @param[in] next Token source function
 * @param[in] source State passed to next
 */
void parser_init(Ctx* ctx, TokenSourceNext next, void* source);

/**
 * @brief Moves to the next token, freeing the current one.
 *
 * Raw tokens are translated before the parser sees them: WHITESPACE is dropped
 * and raw indents become block open / block close INDENT tokens (see
 * GLOSSARY.md, Raw indent).
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 */
void parser_advance(Ctx* ctx, Parser* parser);

/**
 * @brief Returns the token after the current token without consuming it.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 * @return The peeked token, owned by the parser, valid until the next advance
 */
const Token* parser_peek(Ctx* ctx, Parser* parser);

/**
 * @brief Consumes the current token if it has given type, otherwise throws a
 * syntax error.
 *
 * The consumed token is freed; read its value (e.g. an identifier's text)
 * before calling.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 * @param[in] type Expected token type
 */
void parser_expect(Ctx* ctx, Parser* parser, TokenType type);

/**
 * @brief Consumes the current token if it has given type.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 * @param[in] type Accepted token type
 * @return Whether the token was consumed
 */
bool parser_accept(Ctx* ctx, Parser* parser, TokenType type);

/**
 * @brief Throws a syntax error at the current token.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in] parser Parser state
 * @param[in] expected Description of what was expected, e.g. "IDENT or ("
 */
void parser_syntax_error(Ctx* ctx, const Parser* parser, const char* expected);

/**
 * @brief Returns a readable name of given token type for diagnostics
 */
const char* parser_token_name(TokenType type);

// === NONTERMINAL FUNCTIONS ===
//
// Prototypes of nonterminal functions the precedence parser calls back into
// (e.g. for expressions that contain statements) go here, see the template in
// parser.c.

#endif
